const cfg=$('CONFIG').first().json;
const names=cfg.direct_meb_source_names||{};
const out=[];
for(const host of (cfg.direct_meb_hosts||[])){
  const base='https://'+host+'/';
  const sourceName=names[host]||'Millî Eğitim Bakanlığı';
  out.push({json:{
    fetch_url:'http://127.0.0.1:10000/discover?url='+encodeURIComponent(base)+'&source_name='+encodeURIComponent(sourceName),
    source_host:host,source_name:sourceName,source_type:'DISCOVER',official_base:base
  }});
}
return out;

const cfg=$('CONFIG').first().json;
const meta=$('KAYNAKLARI ÜRET').all();
const store=$getWorkflowStaticData('global');
store.directSeen=store.directSeen||{};
store.publishedNews=store.publishedNews||{};
const now=Date.now();
const keepMs=Number(cfg.seen_keep_days||21)*86400000;
for(const [k,v] of Object.entries(store.directSeen)){ if(!v||now-Number(v)>keepMs) delete store.directSeen[k]; }

function clean(s=''){return String(s||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();}
function hash(s=''){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return(h>>>0).toString(16);}
function canon(u=''){try{const x=new URL(u);x.hash='';x.search='';return(x.hostname+x.pathname.replace(/\/$/,'')).toLowerCase();}catch(e){return String(u||'').toLowerCase();}}
function articleUrl(u=''){return /^https:\/\/[^/]*meb\.gov\.tr\/.*\/(?:haber|icerik)\/\d+(?:\/tr)?\/?(?:[?#].*)?$/i.test(String(u||''));}
function publishedKeys(url='',title='',source=''){return ['url:'+hash(canon(url)),'src-title:'+hash(clean(source).toLowerCase()+'|'+clean(title).toLowerCase())];}

const found=[];
let ok=0,failed=0,discovered=0,seen=0;
const inputs=$input.all();
for(let i=0;i<inputs.length;i++){
  const j=inputs[i]?.json||{};
  const md=meta[i]?.json||{};
  const payload=(j.raw!==undefined&&j.raw!==null)?j.raw:((j.data!==undefined&&j.data!==null)?j.data:j.body);
  if(payload===undefined||payload===null||payload===''){failed++;continue;}
  let obj=null;
  if(payload && typeof payload==='object'){
    obj=payload;
  }else{
    try{obj=JSON.parse(String(payload));}catch(e){failed++;continue;}
  }
  if(obj?.ok!==true||!Array.isArray(obj.items)){failed++;continue;}
  ok++;
  for(const v of obj.items){
    const link=String(v.link||v.official_source_url||'').trim();
    const title=clean(v.title);
    if(!title||!articleUrl(link))continue;
    discovered++;
    const source=clean(v.source_name||md.source_name||'Millî Eğitim Bakanlığı');
    const keys=publishedKeys(link,title,source);
    const directKey=hash(canon(link)+'|'+title.toLocaleLowerCase('tr-TR'));
    if(store.directSeen[directKey]||keys.some(k=>store.publishedNews[k])){seen++;continue;}
    const full=clean(v.source_content||v.summary||'');
    found.push({json:{
      title,link,official_source_url:link,
      published:String(v.published||''),
      summary:clean(v.summary||'').slice(0,2400),
      source_content:full.slice(0,9000),
      source_page_summary:clean(v.summary||''),
      source_image_url:String(v.source_image_url||''),
      source_image_credit:clean(v.source_image_credit||source),
      source_name:source,
      source_host:md.source_host||'',
      source_type:'DISCOVER',
      verified:true,meb_relevant:true,
      direct_seen_key:directKey,
      ts:Number(v.ts||0)||now,
      article_enriched:full.length>=120,
      article_fetch_ok:full.length>=120
    }});
  }
}
const uniq=new Map();
for(const x of found){
  const k=canon(x.json.link);
  if(!uniq.has(k))uniq.set(k,x);
}
const arr=[...uniq.values()].sort((a,b)=>Number(b.json.ts||0)-Number(a.json.ts||0));
const maxPick=Math.max(1,Number(cfg.max_items_per_run||3));
const picked=arr.slice(0,maxPick);
if(!picked.length){
  return [{json:{status_only:true,run_mode:String(cfg.run_mode||'normal'),DURUM:'RESMÎ MEB KAYNAKLARI TARANDI — YENİ YAYIN ADAYI YOK',publish_telegram:false,publish_instagram:false,publish_threads:false,publish_facebook:false,scan_debug:{input:inputs.length,ok,failed,discovered,seen,eligible:0,picked:0}}}];
}
return picked.map((x,i)=>({json:{...x.json,item_id:i,run_mode:String(cfg.run_mode||'normal'),scan_debug:{input:inputs.length,ok,failed,discovered,seen,eligible:arr.length,picked:picked.length}}}));

const cfg=$('CONFIG').first().json;
const store=$getWorkflowStaticData('global');
store.directSeen=store.directSeen||{};
store.qualityRejected=store.qualityRejected||{};
const now=Date.now();
const all=$input.all();
for(const item of all){
  const j=item?.json||{};
  if(j.status_only===true) continue;
  const enough=j.article_enriched===true && Number(j.source_content_chars||0)>=120 && String(j.source_content||'').trim().length>=120;
  if(!enough){
    const key=String(j.direct_seen_key||'').trim();
    if(key) store.directSeen[key]=now;
    const url=String(j.official_source_url||j.link||key||('insufficient-'+now));
    store.qualityRejected[url]={at:now,reasons:['SOURCE_CONTENT_INSUFFICIENT'],title:String(j.title||'').slice(0,180)};
  }
}
const sources=all
  .filter(x=>x.json?.status_only!==true && x.json?.article_enriched===true && Number(x.json?.source_content_chars||0)>=120 && String(x.json?.source_content||'').trim().length>=120)
  .slice(0,Math.max(1,Number(cfg.max_items_per_run||1)))
  .map((item,index)=>({...item.json,item_id:index}));
if(!sources.length)return[];

const itemSchema={type:'object',additionalProperties:false,properties:{
  item_id:{type:'integer'},importance:{type:'integer'},
  category:{type:'string'},title_main:{type:'string'},title_highlight:{type:'string'},hook:{type:'string'},summary:{type:'string'},
  bullet_1:{type:'string'},bullet_2:{type:'string'},bullet_3:{type:'string'},
  source_name:{type:'string'},official_source_url:{type:'string'},
  hashtags:{type:'array',items:{type:'string'},minItems:5,maxItems:8}
},required:['item_id','importance','category','title_main','title_highlight','hook','summary','bullet_1','bullet_2','bullet_3','source_name','official_source_url','hashtags']};
const schema={type:'object',additionalProperties:false,properties:{results:{type:'array',minItems:1,items:itemSchema}},required:['results']};

const haberler=sources.map(s=>({
  item_id:s.item_id,
  source_title:String(s.title||''),
  published:String(s.published||''),
  link:String(s.official_source_url||s.link||''),
  source_name:String(s.source_name||'Millî Eğitim Bakanlığı'),
  source_article:String(s.source_content||'').replace(/\s+/g,' ').slice(0,8500)
}));

const prompt=[
'EĞİTİM GÜNDEM 365 için profesyonel Türkçe haber editörüsün.',
'SADECE source_article içindeki doğrulanmış gerçekleri kullan. Yeni bilgi, yorum, sonuç, tarih, sayı veya kişi UYDURMA.',
'Her haber için TAM OLARAK şu alanları üret: item_id, importance, category, title_main, title_highlight, hook, summary, bullet_1, bullet_2, bullet_3, source_name, official_source_url, hashtags.',
'',
'ZORUNLU EDİTÖRYAL KURALLAR:',
'- item_id girdideki item_id ile AYNI olacak.',
'- official_source_url girdideki link ile AYNI olacak.',
'- source_name girdideki source_name olacak.',
'- title_main 28-60 karakter: BEYAZ ANA BAŞLIK. Haberin ana olayını sıfırdan ve profesyonel haber diliyle yaz.',
'- title_highlight 18-55 karakter: SARI İKİNCİ BAŞLIK. title_main cümlesinin devamı OLAMAZ; ikinci bir açı, kapsam, sonuç veya önem bilgisi vermeli.',
'- title_main + title_highlight kaynak başlığın aynısı, yakın kopyası veya rastgele ikiye bölünmüş hâli OLAMAZ.',
'- source_title kelime sırasını ve cümle iskeletini KULLANMA.',
'- source_title içinden art arda 3 anlamlı kelimeyi title_main/title_highlight içinde aynen kullanma.',
'- title_main ile title_highlight aynı bilgiyi farklı kelimelerle tekrar ETMEYECEK.',
'- YASAK örnek: source_title="Türkiye-Gürcistan eğitim iş birliği anlaşması imzalandı" -> title_main="Türkiye-Gürcistan eğitim iş" / title_highlight="birliği anlaşması imzalandı".',
'- DOĞRU örnek: title_main="Türkiye ile Gürcistan eğitimde yeni dönem başlattı" / title_highlight="Anlaşma denkliği ve mesleki eğitimi kapsıyor".',
'- Haberin tam gövdesindeki iki farklı editoryal açıyı seç.',
'- hook kısa önem cümlesi; iki başlığı tekrar etme.',
'- summary 120-190 karakterlik profesyonel lead; kaynak cümlesini kopyalama.',
'- summary kaynak cümleyle aynı ilk 4 kelimeyle BAŞLAMAYACAK.',
'- summary içinde kaynaktan art arda 5 veya daha fazla anlamlı kelimeyi aynı sırayla KULLANMA.',
'- Kaynaktaki özne-fiil dizilimini değiştir; gerçekleri koruyarak cümleyi profesyonel haber diliyle yeniden kur.',
'- bullet_1..3: 0-3 ayrı gerçek. Her biri "Kısa alt başlık — tek cümle açıklama" biçiminde. Bilgi yoksa boş string.',
'- category yalnız: MÜFREDAT, ÖĞRETMEN, ÖĞRENCİ, SINAV, ATAMA, YÖNETİCİ, PROJE, TEKNOLOJİ, MESLEKİ EĞİTİM, ÖZEL EĞİTİM, MEVZUAT, DİĞER MEB.',
'- importance 0-100 tamsayı.',
'- hashtags 5-8 kısa etiket.',
'- Markdown yok. Açıklama yok. YALNIZ geçerli JSON döndür: {"results":[...]}',
'',
'HABERLER='+JSON.stringify(haberler)
].join('\n');

const openai_body={
  model:cfg.openai_model,
  store:false,
  reasoning:{effort:'low'},
  max_output_tokens:Math.max(2200,Number(cfg.ai_max_output_tokens||3000)),
  text:{format:{type:'json_schema',name:'eg365_newsroom_package',strict:true,schema}},
  input:prompt
};
return [{json:{sources,openai_body,official_recent_mode:true,content_contract:'EG365_V117_PRO_NEWSROOM'}}];

const cfg=$('CONFIG').first().json;
const telegramPublicUrl=String(cfg.telegram_public_url||'https://t.me/egitimgundem365').trim();
const telegramCta=`📲 Detaylar Telegram'da: ${telegramPublicUrl}`;

function extract(resp){
  if(!resp)return'';
  if(typeof resp.output_text==='string')return resp.output_text;
  for(const o of(resp.output||[]))for(const c of(o.content||[]))if(c.type==='output_text'&&c.text)return c.text;
  if(Array.isArray(resp.choices))return String(resp.choices?.[0]?.message?.content||'');
  return'';
}
function cleanJsonText(s=''){return String(s).replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();}
function cleanText(s=''){return String(s).replace(/<[^>]*>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&#39;/g,"'").replace(/&quot;/g,'"').replace(/\s+/g,' ').trim();}
function officialUrl(url=''){try{const u=new URL(String(url||''));const h=String(u.hostname||'').toLowerCase();return h==='meb.gov.tr'||h.endsWith('.meb.gov.tr');}catch(e){return false;}}
function googleNewsUrl(url=''){return /^https?:\/\/(?:news\.)?google\.com\//i.test(String(url||''));}
function directUrl(url=''){return /^https?:\/\//i.test(String(url||'')) && !googleNewsUrl(url);}
function officialBonus(url=''){
  const u=String(url).toLowerCase();
  if(/meb\.gov\.tr\//.test(u))return 20;
  if(/resmigazete\.gov\.tr|osym\.gov\.tr|\.gov\.tr\//.test(u))return 15;
  return 0;
}
function escHtml(s=''){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function escAttr(s=''){return String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;');}
function uniqueUrls(arr=[]){const out=[];const seen=new Set();for(const u of arr){const s=String(u||'').trim();if(!/^https?:\/\//i.test(s))continue;const k=s.toLowerCase();if(seen.has(k))continue;seen.add(k);out.push(s);}return out;}
function bestSourceUrl(data={},src={}){
  const list=uniqueUrls([
    data.official_source_url,
    data.source_url,
    ...(Array.isArray(data.related_urls)?data.related_urls:[]),
    src.official_source_url,
    ...(Array.isArray(src.related_urls)?src.related_urls:[]),
    src.link
  ]);
  const official=list.find(officialUrl);
  if(official) return official;
  const direct=list.find(directUrl);
  if(direct) return direct;
  return list[0]||'';
}
function relatedSourceUrls(mainUrl,data={},src={}){
  return uniqueUrls([...(Array.isArray(data.related_urls)?data.related_urls:[]),...(Array.isArray(src.related_urls)?src.related_urls:[]),src.link]).filter(u=>u!==mainUrl && !googleNewsUrl(u)).slice(0,2);
}
function categoryOf(t=''){
  t=String(t).toLocaleLowerCase('tr-TR');
  if(/atama|tayin|yer değiş|norm kadro|personel|öğretmen alım/.test(t))return'Atama & Personel';
  // Kurum adlarındaki “Genel Müdürlüğü” sözcüğü yönetici haberi sayılmaz.
  // Yalnızca gerçek yönetici/pozisyon ifadeleri bu kategoriye girer.
  if(/okul müdürü|müdür yardımcısı|şube müdürü|yönetici görevlendirme|yönetici atama|yönetici seçme|yönetici değerlendirme|eğitim kurumu yönetic/.test(t))return'Yönetici Görevlendirme';
  if(/yönetmelik|mevzuat|yönerge|genelge|resm.? gazete|tebliğ/.test(t))return'Mevzuat & Resmî Gazete';
  // Türkçe küçük harfe dönüşümde I -> ı olduğu için uluslararası kısaltmaların iki yazımı da desteklenir.
  if(/(?:^|[^a-z0-9çğıöşü])(?:isa|ısa)(?=$|[^a-z0-9çğıöşü])|pisa|pısa|timss|tımss|pirls|pırls|lgs|iokbs|sınav|ortak yazılı|ölçme|değerlendirme|kpss|araştırma sonuç/.test(t))return'Sınav & Ölçme';
  if(/eba|e-okul|e okul|mebbis|öba|mebi/.test(t))return'EBA/e-Okul/MEBBİS';
  if(/yapay zek|teknoloji|yegitek|fatih|dijital|siber/.test(t))return'Teknoloji & Yapay Zekâ';
  if(/müfredat|maarif|tymm|öğretim program|ders program/.test(t))return'Müfredat & TYMM';
  if(/mesleki|mesem|meslek lises/.test(t))return'Meslekî Eğitim';
  if(/özel eğitim|ram\b|bilsem|kaynaştırma/.test(t))return'Özel Eğitim & Rehberlik';
  if(/burs|pansiyon|yurt dış/.test(t))return'Burs & Yurt Dışı';
  if(/tatil|takvim|eğitim öğretim yılı/.test(t))return'Takvim & Tatil';
  return'Diğer MEB';
}
function sentences(s=''){
  const txt=cleanText(s);
  const parts=txt.split(/(?<=[.!?])\s+/).map(x=>x.trim()).filter(x=>x.length>18);
  if(parts.length)return parts.slice(0,4);
  return txt?[txt]:[];
}
function sameish(a='',b=''){
  const x=cleanText(a).toLocaleLowerCase('tr-TR');
  const y=cleanText(b).toLocaleLowerCase('tr-TR');
  if(!x||!y)return false;
  if(x===y)return true;
  return x.includes(y)||y.includes(x);
}
function uniqFacts(list=[], refs=[]){
  const out=[];
  for(const raw of (list||[])){
    const t=cleanText(raw);
    if(!t)continue;
    if(sourceLikeV89(t,''))continue;
    if(refs.some(r=>sameish(t,r)))continue;
    if(out.some(v=>sameish(v,t)))continue;
    out.push(t);
    if(out.length>=3)break;
  }
  return out;
}
function pickLead(candidates=[], title=''){
  for(const c of candidates||[]){
    const t=cleanText(c);
    if(!t)continue;
    if(sameish(t,title))continue;
    return t.slice(0,190);
  }
  return '';
}
function publisherFromTitle(title=''){
  const t=cleanText(title);
  const m=t.match(/\s[-–—]\s([^\-–—]{2,60})$/);
  return m?m[1].trim():'';
}
function stripPublisher(title=''){return cleanText(title).replace(/\s[-–—]\s[^\-–—]{2,60}$/,'').trim();}
function relevance(text=''){return /\b(meb|milli eğitim|millî eğitim|öğretmen|öğrenci|okul|lgs|iokbs|eba|e okul|e-okul|mebbis|öba|mebi|müfredat|maarif|yönetmelik|yönerge|genelge|atama|görevlendirme|sınav|mesleki eğitim|özel eğitim|bilsem|ram|fatih|yegitek|mesem|akademi|burs|pansiyon|kpss)\b/i.test(cleanText(text));}
function makeSourceFallback(src,reason){
  if(!src)return null;
  const full=cleanText((src.title||'')+' '+(src.summary||''));
  const isOfficial=officialUrl(src.link||src.official_source_url||'');
  // Bu node'a ulaşan kaynaklar ÖN FİLTRE tarafından resmî MEB olarak doğrulanmıştır.
  // AI, resmî kaynağı yanlışlıkla 'ilgili değil/doğrulanmadı' dese bile haberi veto edemez.
  if(!isOfficial && cfg.fail_open_source_reporting!==true && !relevance(full))return null;
  const ss=sentences(src.summary||'');
  let bullets=ss.filter(x=>!sourceLikeV89(x,src.source_name||'')).slice(0,3);
  const pub=publisherFromTitle(src.title||'');
  return {
    item_id:Number(src.item_id||0),
    meb_relevant:true,
    verified:isOfficial,
    source_reported:!isOfficial,
    confidence:isOfficial?94:74,
    importance:Number(src.important||0)?78:55,
    category:categoryOf(full),
    title_main:stripPublisher(src.title||'').slice(0,112),
    title_highlight:'',
    lead:(ss[0]||stripPublisher(src.title||'')).slice(0,190),
    bullets:bullets.map(x=>cleanText(x).slice(0,180)).filter(Boolean).slice(0,3),
    source_name:isOfficial?(/osym/i.test(src.link||'')?'ÖSYM Başkanlığı':(/resmigazete/i.test(src.link||'')?'Resmî Gazete':'Millî Eğitim Bakanlığı')):(pub||'Haber kaynağı'),
    official_source_url:isOfficial?String(src.link||src.official_source_url||''):'',
    related_urls:[],
    hashtags:['#MEB','#Eğitim','#MilliEğitim','#EğitimGündemi','#Öğretmen'],
    publish_telegram:true,publish_instagram:true,
    _ai_status:'SOURCE_FALLBACK_'+reason,
    _publication_basis:isOfficial?'OFFICIAL_SOURCE_FALLBACK':'SOURCE_REPORTED_FALLBACK'
  };
}
function normalize(data,src){
  const d={...(data||{})};
  d.item_id=Number(d.item_id??src?.item_id??0);
  if(src){
    d.meb_relevant=true;
    d.verified=true;
    d.source_reported=false;
    d.confidence=Math.max(100,Number(d.confidence||0));
    d.publish_telegram=true;
    d.publish_instagram=true;
    d.official_source_url=String(src.official_source_url||src.link||d.official_source_url||'');
    d.source_name=cleanText(src.source_name||d.source_name||'Millî Eğitim Bakanlığı');
  }
  d.title_main=cleanText(d.title_main||'');
  d.title_highlight=cleanText(d.title_highlight||'');
  d.lead=cleanText(d.lead||'');
  if(!d.lead || sameish(d.lead,d.title_main)){
    d.lead=pickLead([
      d.summary,
      ...(Array.isArray(src?.summary)?src.summary:[src?.summary]),
      src?.source_content,
      src?.description,
      src?.contentSnippet
    ], d.title_main) || d.title_main;
  }
  let b=Array.isArray(d.bullets)?d.bullets.map(cleanText).filter(Boolean):[];
  b=uniqFacts(b,[d.title_main,d.lead]).filter(x=>!sourceLikeV89(x,d.source_name||'')).slice(0,3);
  d.bullets=b.map(x=>x.slice(0,160));
  const _cats=new Set(['MÜFREDAT','ÖĞRETMEN','ÖĞRENCİ','SINAV','ATAMA','YÖNETİCİ','PROJE','TEKNOLOJİ','MESLEKİ EĞİTİM','ÖZEL EĞİTİM','MEVZUAT','DİĞER MEB']); if(!_cats.has(cleanText(d.category||'').toLocaleUpperCase('tr-TR')))d.category=categoryOf((src?.title||'')+' '+(src?.summary||''));
  if(!cleanText(d.source_name||''))d.source_name=publisherFromTitle(src?.title||'')||'Haber kaynağı';
  if(!Array.isArray(d.hashtags)||d.hashtags.filter(Boolean).length<5)d.hashtags=['#MEB','#Eğitim','#MilliEğitim','#EğitimGündemi','#Öğretmen'];
  if(!Array.isArray(d.related_urls))d.related_urls=[];
  d.publish_telegram=true;
  d.publish_instagram=true;
  d.publish_threads=true;
  d.publish_facebook=true;
  return d;
}

const response=$input.first()?.json||{};
const bundle=$('OPENAI TOPLU İSTEK HAZIRLA').first().json||{};
const sources=(bundle.sources||[]).map((s,i)=>({...s,item_id:Number.isFinite(Number(s.item_id))?Number(s.item_id):i}));
const sourceById=new Map(sources.map((s,i)=>[Number(s.item_id??i),s]));
let rawResults=[];
let aiStatus='AI_OK';
let aiError='';
const aiModelUsed=response._router_model||response.model||'unknown';

if(response.error){
  aiError=String(response.error.message||response.error.description||'API_ERROR');
  aiStatus=/rate limit|too many requests|429/i.test(aiError)?'RATE_LIMIT_429':'API_ERROR';
}else{
  try{
    const parsed=JSON.parse(cleanJsonText(extract(response)));
    rawResults=Array.isArray(parsed.results)?parsed.results:[];
  }catch(e){aiStatus='JSON_PARSE_ERROR';aiError=String(e.message||e);}
}

let results=[];
for(const r of rawResults){
  const id=Number(r?.item_id);
  const ru=String(r?.official_source_url||r?.source_url||'').trim().toLowerCase();
  const src=sourceById.get(id)
    || sources.find(s=>ru && String(s.official_source_url||s.link||'').trim().toLowerCase()===ru)
    || (sources.length===1?sources[0]:sources[id]);
  if(src)results.push(normalize(normalizeV89Result(r),src));
}
