// V92: Fail-closed kalite kapısı + özgünlük kontrolü + reddedilen adayı tekrar seçmeme
const out=[];
const store=$getWorkflowStaticData('global');
store.directSeen=store.directSeen||{};
store.qualityRejected=store.qualityRejected||{};
const now=Date.now();
const leadBadTail=/\b\d+\.$/;
const badEnd=/(?:—|-|–|:|;|,|\bve|\bile|\biçin|\bicin|\bolarak|\bolan|\bbir|\bbu)$/i;
const badVerb=/(?:\bma|\bme|\bmak|\bmek|ması|mesi)$/i;

function reject(j,reasons){
  const key=String(j.direct_seen_key||'').trim();
  if(key) store.directSeen[key]=now;
  const rkey=String(j.official_source_url||j.source_url||j.link||key||('rej-'+now));
  store.qualityRejected[rkey]={at:now,reasons,title:String(j.title_main||j.title||'').slice(0,180)};
}
for(const item of $input.all()){
  const j=item?.json||{};
  const reasons=[];
  const url=String(j.official_source_url||j.source_url||j.preferred_source_url||j.link||'').trim();
  const title=String(j.title_main||j.title||j.image_title||'').trim();
  const summary=String(j.summary||j.lead||'').trim();
  const realCandidate=Boolean(url&&title&&(summary||j.status_only!==true));
  if(j.status_only===true&&!realCandidate) continue;

  if(j.verified!==true) reasons.push('SOURCE_NOT_VERIFIED');
  const imageUrl=String(j.source_image_url||'').trim();
  const imageMethod=String(j.source_image_method||'').trim().toLowerCase();
  const realImage=j.source_image_found===true&&/^https?:\/\//i.test(imageUrl)&&imageMethod!=='placeholder';
  if(!realImage) reasons.push('REAL_IMAGE_MISSING');

  const lead=String(j.lead||j.summary||'').replace(/\s+/g,' ').trim();
  const leadComplete=lead.length>=120&&lead.length<=230&&/[.!?]$/.test(lead)&&!leadBadTail.test(lead);
  if(!leadComplete) reasons.push('LEAD_INCOMPLETE');

  const bullets=(Array.isArray(j.bullets)?j.bullets:[j.bullet_1,j.bullet_2,j.bullet_3])
    .map(x=>String(x||'').replace(/\s+/g,' ').trim()).filter(Boolean).slice(0,3);
  const bulletsComplete=bullets.every(t=>{
    const core=t.replace(/[.!?]+$/,'').trim();
    const last=(core.match(/([^\s]+)$/)||[])[1]||'';
    return /[.!?]$/.test(t)&&!/[—–-]\s*$/.test(core)&&!badEnd.test(core)&&last.length>2&&!badVerb.test(last);
  });
  if(!bulletsComplete) reasons.push('BULLET_INCOMPLETE');

  if(j._newsroom?.quality_gate!=='PASS') reasons.push('EDITOR_GATE_BLOCK');

  const leadSim=Number(j.lead_similarity||0);
  const leadSentenceSim=Number(j.lead_sentence_similarity||0);
  const titleSim=Number(j.title_similarity||0);
  if(leadSim>0.85||leadSentenceSim>0.90) reasons.push('LEAD_TOO_SIMILAR');
  const normWords=s=>String(s||'').toLocaleLowerCase('tr-TR').replace(/[^a-z0-9çğıöşü\s]/gi,' ').split(/\s+/).filter(Boolean);
  const lw=normWords(lead), sw=normWords(j.source_content||j.source_page_description||'');
  if(lw.length>=4&&sw.length>=4&&lw.slice(0,4).join(' ')==sw.slice(0,4).join(' ')&&leadSim>0.75) reasons.push('LEAD_SAME_START_HIGH_SIM');
  if(titleSim>0.80) reasons.push('TITLE_TOO_SIMILAR');

  const stop=new Set(['ve','ile','için','icin','olan','olarak','bir','bu','şu','daha','çok','gibi','kadar','tarafından','kapsamında','amacıyla','amaciyla','yönelik','yonelik']);
  function terms(s){
    return String(s||'').toLocaleLowerCase('tr-TR').replace(/[^a-z0-9çğıöşü\s]/gi,' ').split(/\s+/)
      .filter(x=>x.length>=4&&!stop.has(x));
  }
  function groundedRatio(text,source){
    const a=terms(text), b=terms(source);
    if(!a.length||!b.length)return 0;
    let hit=0;
    for(const x of a){
      const exact=/^\d+$/.test(x);
      if(b.some(y=>exact?y===x:(x===y||(x.length>=5&&y.length>=5&&x.slice(0,5)===y.slice(0,5)))))hit++;
    }
    return hit/a.length;
  }
  const sourceFacts=String(j.source_content||j.source_page_description||'');
  const mainGround=groundedRatio(j.title_main,sourceFacts);
  const hiGround=groundedRatio(j.title_highlight,sourceFacts);
  const leadGround=groundedRatio(lead,sourceFacts);
  if(mainGround<0.40) reasons.push('TITLE_NOT_GROUNDED');
  if(hiGround<0.40) reasons.push('HIGHLIGHT_NOT_GROUNDED');
  if(leadGround<0.50) reasons.push('LEAD_NOT_GROUNDED');
  for(const b of bullets){if(groundedRatio(b,sourceFacts)<0.50){reasons.push('BULLET_NOT_GROUNDED');break;}}

  if(reasons.length){reject(j,reasons);continue;}

  out.push({json:{...j,status_only:false,bullets,bullet_1:bullets[0]||'',bullet_2:bullets[1]||'',bullet_3:bullets[2]||'',bullet_count:bullets.length,_candidate_gate_passed:true,_candidate_gate_version:'V95_BALANCED_ORIGINALITY_GROUNDED'}});
}
return out;

