  const oldEnd=Number(store.backfill5.endTs||0);
  if(previousHeartbeat && gapMs>=AUTO_GAP){
    const recoveryStart=Math.max(now-MAX_LOOKBACK,previousHeartbeat-SAFETY);
    store.backfill5.startTs=oldStart?Math.min(oldStart,recoveryStart):recoveryStart;
    store.backfill5.endTs=now;
